{
  "part": {
    "name": "Combination open-jaw and ring wrench",
    "description": "A single-piece, constant-thickness wrench-like tool with a large open jaw at one end, a circular ring interface at the opposite end, and a long rectangular handle containing a shallow rounded-corner recess on its upper face. The STEP model is one solid with 26 faces, comprising 12 planar and 14 cylindrical faces.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "The part is approximately bilaterally symmetric about its longitudinal center plane and has a nominally uniform 15 mm thickness. The STEP data shows small left-right differences in the fitted outer cylindrical profiles and handle offsets, so symmetry is approximate rather than exact."
  },
  "Section": [
    {
      "id": "SEC-01",
      "name": "Open jaw head",
      "features included": [
        "Open-ended fastener interface",
        "Two opposing jaw arms",
        "Parallel inner jaw flats",
        "Rounded slot-root corners",
        "Large curved outer head flanks",
        "U-shaped internal cavity"
      ],
      "function intent": "Engages a nut, bolt head, or other two-flat component from the side so the tool can apply torque without requiring axial access over the fastener.",
      "physical behavior": "The two inner flats react opposite contact forces from the fastener. Torque is carried around the rounded slot root into the outer jaw arms and then into the handle. The generous outer curves and root radii spread bending stress and reduce stress concentration at the base of the opening.",
      "geometry": "A broad, approximately circular open-end head split by a centered U-shaped slot. The slot has two longitudinal planar walls, a transverse planar root, and cylindrical root blends. Large cylindrical patches form the external left and right jaw contours.",
      "location": "At the negative-Z end of the part, opposite the circular ring end; shown at the upper end in the top and bottom views.",
      "colour": {
        "R": 220,
        "G": 72,
        "B": 72
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Right outer jaw curve",
          "Brep_id": "FACE 16",
          "description": "Large cylindrical external surface forming the right-hand curved jaw arm and outer head perimeter."
        },
        {
          "face_code": "0001",
          "name": "Right inner jaw flat",
          "Brep_id": "FACE 22",
          "description": "Planar inner wall at x=10 extending from the jaw tip toward the rounded slot root."
        },
        {
          "face_code": "0002",
          "name": "Right slot-root blend",
          "Brep_id": "FACE 17",
          "description": "Radius-5 cylindrical corner joining the right inner jaw flat to the transverse slot-root face."
        },
        {
          "face_code": "0003",
          "name": "Slot-root flat",
          "Brep_id": "FACE 18",
          "description": "Transverse planar surface closing the base of the open-ended U-shaped fastener slot."
        },
        {
          "face_code": "0004",
          "name": "Left slot-root blend",
          "Brep_id": "FACE 19",
          "description": "Radius-5 cylindrical corner joining the slot-root flat to the left inner jaw flat."
        },
        {
          "face_code": "0005",
          "name": "Left inner jaw flat",
          "Brep_id": "FACE 20",
          "description": "Planar inner wall at x=-10 extending from the rounded slot root to the left jaw tip."
        },
        {
          "face_code": "0006",
          "name": "Left outer jaw curve",
          "Brep_id": "FACE 23",
          "description": "Large cylindrical external surface forming the left-hand curved jaw arm and outer head perimeter."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC-01",
          "target id": "SEC-02",
          "function relationship": "transmits_load; distributes_stress",
          "structural relationship": "attached_to; blends_into; supported_by"
        },
        {
          "source id": "SEC-01",
          "target id": "SEC-04",
          "function relationship": "provides an alternative fastener interface at the opposite end",
          "structural relationship": "offset_from; connected_through SEC-02"
        }
      ]
    },
    {
      "id": "SEC-02",
      "name": "Handle and continuous body",
      "features included": [
        "Long torque-transmitting spine",
        "Parallel longitudinal side walls",
        "Continuous upper body land",
        "Continuous lower body face",
        "Rounded transitions to both end heads",
        "Constant-thickness structural web"
      ],
      "function intent": "Provides hand leverage and structurally connects the open jaw to the ring end while carrying torque and bending loads between the user's grip and either working interface.",
      "physical behavior": "The long rectangular web behaves primarily as a beam under bending and torsion. Its broad upper and lower faces resist bending, while the full-depth side walls carry shear. Cylindrical transition bands at both ends smooth changes in width and distribute stress into the larger heads.",
      "geometry": "An elongated, nearly rectangular bar approximately 20 mm wide and 15 mm thick, bounded by two long planar side faces. Curved transition patches connect the bar to the wider open-jaw head and the circular ring end. The STEP model uses one continuous top planar face and one continuous bottom planar face across the handle and both heads.",
      "location": "Central longitudinal portion between the open jaw head and circular ring end.",
      "colour": {
        "R": 66,
        "G": 135,
        "B": 245
      },
      "major_faces": [
        {
          "face_code": "0007",
          "name": "Left ring transition",
          "Brep_id": "FACE 11",
          "description": "Radius-5 cylindrical blend carrying the left handle side into the outer ring-end profile."
        },
        {
          "face_code": "0008",
          "name": "Left handle side",
          "Brep_id": "FACE 10",
          "description": "Long planar full-thickness side wall along the left side of the central handle."
        },
        {
          "face_code": "0009",
          "name": "Left open-head transition",
          "Brep_id": "FACE 9",
          "description": "Radius-5 cylindrical blend between the left handle side and the widening open-jaw head."
        },
        {
          "face_code": "0010",
          "name": "Continuous upper body land",
          "Brep_id": "FACE 24",
          "description": "Main planar face at y=15 spanning the handle, ring end, and open-jaw head around the recess, ring hole, and open slot."
        },
        {
          "face_code": "0011",
          "name": "Right open-head transition",
          "Brep_id": "FACE 15",
          "description": "Radius-5 cylindrical blend between the right handle side and the widening open-jaw head."
        },
        {
          "face_code": "0012",
          "name": "Right handle side",
          "Brep_id": "FACE 14",
          "description": "Long planar full-thickness side wall along the right side of the central handle."
        },
        {
          "face_code": "0013",
          "name": "Right ring transition",
          "Brep_id": "FACE 13",
          "description": "Radius-5 cylindrical blend carrying the right handle side into the outer ring-end profile."
        },
        {
          "face_code": "0014",
          "name": "Continuous lower body face",
          "Brep_id": "FACE 25",
          "description": "Large uninterrupted planar underside at y=0 spanning the handle and both end heads, interrupted only by the ring opening and outer open-jaw boundary."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC-02",
          "target id": "SEC-01",
          "function relationship": "transmits_load; distributes_stress; supports",
          "structural relationship": "attached_to; blends_into; shares_face"
        },
        {
          "source id": "SEC-02",
          "target id": "SEC-03",
          "function relationship": "supports grip feature; provides material around recess",
          "structural relationship": "contains; adjacent_to; shares_edges"
        },
        {
          "source id": "SEC-02",
          "target id": "SEC-04",
          "function relationship": "transmits_load; distributes_stress; supports",
          "structural relationship": "attached_to; blends_into; shares_face"
        }
      ]
    },
    {
      "id": "SEC-03",
      "name": "Upper handle recess",
      "features included": [
        "Shallow rectangular cavity",
        "Flat recessed floor",
        "Two long cavity side walls",
        "Two transverse end walls",
        "Four rounded vertical corner bands",
        "Grip and mass-relief feature"
      ],
      "function intent": "Provides a visually and tactilely defined grip area while removing a small amount of material and preserving a raised perimeter rim along the handle.",
      "physical behavior": "The approximately 1 mm deep recess reduces local surface height and mass without penetrating the handle. The surrounding rim retains most of the handle's bending section, while the rounded cavity corners reduce local notch stresses and avoid sharp internal corners.",
      "geometry": "A long, shallow, rounded-rectangle pocket in the upper handle face. Its planar floor lies at y=14, one millimetre below the main top face at y=15. Four planar walls and four radius-1 cylindrical corner patches bound the pocket.",
      "location": "Centered on the upper face of the central handle, extending longitudinally between the two end-head transition zones.",
      "colour": {
        "R": 245,
        "G": 181,
        "B": 54
      },
      "major_faces": [
        {
          "face_code": "0015",
          "name": "Recess floor",
          "Brep_id": "FACE 1",
          "description": "Large planar rounded-rectangle floor at y=14 forming the bottom of the shallow handle pocket."
        },
        {
          "face_code": "0016",
          "name": "Ring-end recess wall",
          "Brep_id": "FACE 2",
          "description": "Short transverse planar wall at the positive-Z end of the recess."
        },
        {
          "face_code": "0017",
          "name": "Ring-end right corner",
          "Brep_id": "FACE 5",
          "description": "Small radius-1 cylindrical corner joining the ring-end wall to the right longitudinal recess wall."
        },
        {
          "face_code": "0018",
          "name": "Right recess wall",
          "Brep_id": "FACE 4",
          "description": "Long planar wall forming the right side of the shallow upper recess."
        },
        {
          "face_code": "0019",
          "name": "Jaw-end right corner",
          "Brep_id": "FACE 3",
          "description": "Small radius-1 cylindrical corner joining the right recess wall to the jaw-end wall."
        },
        {
          "face_code": "0020",
          "name": "Jaw-end recess wall",
          "Brep_id": "FACE 8",
          "description": "Short transverse planar wall at the negative-Z, open-jaw end of the recess."
        },
        {
          "face_code": "0021",
          "name": "Jaw-end left corner",
          "Brep_id": "FACE 6",
          "description": "Small radius-1 cylindrical corner joining the jaw-end wall to the left longitudinal recess wall."
        },
        {
          "face_code": "0022",
          "name": "Left recess wall",
          "Brep_id": "FACE 7",
          "description": "Long planar wall forming the left side of the shallow upper recess."
        },
        {
          "face_code": "0023",
          "name": "Ring-end left corner",
          "Brep_id": "FACE 0",
          "description": "Small radius-1 cylindrical corner joining the left recess wall to the ring-end wall."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC-03",
          "target id": "SEC-02",
          "function relationship": "provides grip definition; provides clearance; reduces mass",
          "structural relationship": "contained_in; recessed_into; adjacent_to"
        }
      ]
    },
    {
      "id": "SEC-04",
      "name": "Ring end",
      "features included": [
        "Circular through-hole",
        "Annular load-bearing eye",
        "External circular perimeter",
        "Closed fastener or hanging interface"
      ],
      "function intent": "Provides a closed circular interface that can receive a cylindrical pin, act as a hanging or mounting eye, or surround a compatible fastener depending on the intended application.",
      "physical behavior": "The inner cylindrical wall transfers radial bearing loads into the surrounding annulus. The enlarged external ring distributes those loads around the hole and into the handle through the two rounded neck transitions. As a closed loop, it constrains radial translation of an inserted mating member while permitting rotation about the hole axis when clearance exists.",
      "geometry": "A thick annular end feature with a nominal 10 mm radius through-hole and an approximately 15 mm outer radius. The hole axis is aligned with the part thickness direction. The outer circumference blends into the narrower handle on both sides.",
      "location": "At the positive-Z end of the part, opposite the open jaw; shown at the lower end in the top and bottom views.",
      "colour": {
        "R": 81,
        "G": 190,
        "B": 121
      },
      "major_faces": [
        {
          "face_code": "0024",
          "name": "Outer ring perimeter",
          "Brep_id": "FACE 12",
          "description": "Large cylindrical external patch forming the free outer circumference of the annular ring end."
        },
        {
          "face_code": "0025",
          "name": "Ring through-hole wall",
          "Brep_id": "FACE 21",
          "description": "Full-thickness cylindrical wall of the radius-10 circular through-hole."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC-04",
          "target id": "SEC-02",
          "function relationship": "transmits_load; locates_mating_part; constrains_dof; mounts_to",
          "structural relationship": "attached_to; blends_into; supported_by"
        },
        {
          "source id": "SEC-04",
          "target id": "SEC-01",
          "function relationship": "provides an alternative closed interface to the open-jaw interface",
          "structural relationship": "offset_from; connected_through SEC-02"
        }
      ]
    }
  ]
}
